import hashlib

def sha256(b): return hashlib.sha256(b).digest()

def mth(leaves):
    n = len(leaves)
    if n == 0:
        return sha256(b"")
    if n == 1:
        return sha256(b"\x00" + leaves[0])
    k = 1 << ((n - 1).bit_length() - 1)
    return sha256(b"\x01" + mth(leaves[:k]) + mth(leaves[k:]))

# 固定记录：含重复内容 "alpha"（位置 0 和 2）、两条空记录（位置 3 和 5）
r = [b"alpha", b"beta", b"alpha", b"", b"gamma", b"", b"delta", b"epsilon", b"zeta"]

b7 = r[:7]
b8 = r[:8]
b9 = r[:9]

# 变体1：重复内容 "alpha" 的第二个位置（索引2）改为 "omega"
v1 = r[:2] + [b"omega"] + r[3:]
# 变体2：交换两条不同内容记录（索引1 "beta" 与索引4 "gamma"）
v2 = r[:]; v2[1], v2[4] = v2[4], v2[1]

for name, batch in [("B7", b7), ("B8", b8), ("B9", b9), ("V1(dup->omega)", v1), ("V2(swap beta/gamma)", v2)]:
    print(name, mth(batch).hex())

print("empty-file", sha256(b"").hex())
print("single-LF ", sha256(b"\x00").hex())

# 自检：末尾 LF 不影响记录划分
def split(data):
    if not data: return []
    recs = data.split(b"\n")
    if data.endswith(b"\n"): recs.pop()
    return recs
assert mth(split(b"\n".join(b9))) == mth(split(b"\n".join(b9) + b"\n"))
print("trailing-LF equivalence: OK")
